import React from "react";
import '../css/login.css';
import { FaPhoneAlt } from "react-icons/fa";

class Login extends React.Component {
    render() {
        return (
            <main className="container-fluid vh-100 d-flex align-items-center justify-content-center p-0">
                <img src="../img/aaa.png" alt="fixed logo" className="fixed-top-left" />
                <div className="login-box-login shadow text-center item-back boder p-4 rounded-5">
                    <div className="welcome-box">
                        <img src="../img/aaa.png" alt="logo" className="mb-3" style={{ width: '80px' }} />
                        <h4 className="mb-3 fw-bold">ورود به حساب کاربری</h4>
                        <p className="text-muted small">برای ورود، شماره موبایل خود را وارد کنید</p>

                        <form className="mt-4">
                            {/* فیلد با فلوتینگ لیبل و آیکون */}
                            <div className="form-floating mb-3 position-relative">
                                <input
                                    type="tel"
                                    id="phone"
                                    className="form-control form-control-lg rounded-4 pe-5"
                                    placeholder=" "
                                    dir="rtl"
                                />
                                <label htmlFor="phone" className="pe-5">شماره موبایل</label>
                                <FaPhoneAlt className="position-absolute top-50 end-0 translate-middle-y me-3 text-secondary" />
                            </div>

                            <button type="submit" className="btn btn-primary w-100 rounded-4 py-2 fw-bold">
                                ارسال کد تایید
                            </button>
                        </form>

                        <div className="mt-3 small text-muted">
                            با ورود، قوانین و حریم خصوصی را می‌پذیرید.
                        </div>
                    </div>
                </div>
            </main>
        );
    }
}

export default Login;
